package dev.gyeopdam.embeddedtor;

import java.io.IOException;
import java.util.*;
import java.util.concurrent.Executor;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;

/** Exercises the production coordinator with controlled disk/HTTP completion order. */
public class PeerBlockCoordinatorTest {
    static final String ORIGIN="http://"+"a".repeat(56)+".onion",ACCOUNT="demo-account-a",PEER="demo-peer-a";
    static AppSessionStore.Session owner(String account){return new AppSessionStore.Session(ORIGIN,account,"","","","gd_sess_"+"A".repeat(43));}
    static JSONObject json(boolean blocked,int revision,String mutation)throws Exception{return new JSONObject().put("peer_id",PEER).put("blocked",blocked).put("revision",revision).put("mutation_id",mutation).put("legacy_hold",false);}
    static PeerBlockState state(boolean blocked,int revision,String mutation)throws Exception{return PeerBlockState.parse(json(blocked,revision,mutation),PEER);}
    static final class Queue implements Executor {final ArrayDeque<Runnable> work=new ArrayDeque<>();public void execute(Runnable r){work.add(r);}void drain(){while(!work.isEmpty())work.remove().run();}}
    static final class Store implements PeerBlockCoordinator.Journal {
        final Map<String,PeerBlockJournal.Pending> pending=new LinkedHashMap<>();final Map<String,PeerBlockJournal.Status> statuses=new LinkedHashMap<>();boolean failLoad,failConfirm;int writes;
        public List<PeerBlockJournal.Pending> load()throws IOException{if(failLoad)throw new IOException("FAILED");return new ArrayList<>(pending.values());}
        public List<PeerBlockJournal.Status> loadStatuses()throws IOException{if(failLoad)throw new IOException("FAILED");return new ArrayList<>(statuses.values());}
        public void prepare(PeerBlockJournal.Pending p)throws IOException{PeerBlockJournal.Pending old=pending.get(p.peerId);if(old!=null&&!old.mutationId.equals(p.mutationId))throw new IOException("CONFLICT");pending.put(p.peerId,p);writes++;}
        public void confirm(PeerBlockJournal.Status s,String ack)throws IOException{if(failConfirm)throw new IOException("FAILED");PeerBlockJournal.Status old=statuses.get(s.peerId);if(old!=null&&old.revision>s.revision)throw new IOException("STALE");
            if(!ack.isEmpty()){PeerBlockJournal.Pending p=pending.get(s.peerId);if(p==null||!p.mutationId.equals(ack)||p.blocked!=s.blocked||(long)p.expectedRevision+1!=s.revision)throw new IOException("WRONG_ACK");pending.remove(s.peerId);}
            if(s.revision!=0||s.blocked)statuses.put(s.peerId,s);writes++;
        }
        public void confirmAll(List<PeerBlockJournal.Status> page)throws IOException{for(PeerBlockJournal.Status s:page)confirm(s,"");}
        public void acknowledge(String peer,String mutation)throws IOException{PeerBlockJournal.Pending p=pending.get(peer);if(p!=null&&!p.mutationId.equals(mutation))throw new IOException("STALE_ACK");pending.remove(peer);writes++;}
        public void resetAfterConfirmation(){pending.clear();statuses.clear();failLoad=false;failConfirm=false;writes++;}
    }
    static final class Request {final String method,path;final JSONObject body;final AppSessionStore.Session owner;final PeerBlockCoordinator.Reply reply;Request(String m,String p,JSONObject b,AppSessionStore.Session o,PeerBlockCoordinator.Reply r){method=m;path=p;body=b;owner=o;reply=r;}}
    static final class Fixture {
        final Queue disk=new Queue();final Map<String,Store> stores=new HashMap<>();final List<Request> requests=new ArrayList<>();final PeerBlockCoordinator core;
        Fixture(){core=new PeerBlockCoordinator((origin,account)->stores.computeIfAbsent(origin+account,k->new Store()),(m,p,b,o,r)->requests.add(new Request(m,p,b,o,r)),disk,Runnable::run,()->{});core.bindSession(owner(ACCOUNT));disk.drain();}
        Store store(){return stores.get(ORIGIN+ACCOUNT);}Request last(){return requests.get(requests.size()-1);}
        void ack(boolean desired)throws Exception{Request r=last();r.reply.complete(200,json(desired,r.body.getInt("expected_revision")+1,r.body.getString("mutation_id")),"");}
    }
    @Test public void durableIntentPrecedesFirstHttpAndBlocksLocalSending()throws Exception {Fixture f=new Fixture();List<String> result=new ArrayList<>();f.core.submit(state(false,0,""),true,(s,e)->result.add(e));assertEquals(0,f.requests.size());assertTrue(f.store().pending.isEmpty());f.disk.drain();assertEquals(1,f.requests.size());assertEquals(1,f.store().pending.size());assertTrue(f.core.blocksSending(PEER));assertTrue(result.isEmpty());assertNull(f.core.known(PEER));}
    @Test public void cancelledNavigationStillReconcilesCommittedPendingIntent()throws Exception {Fixture f=new Fixture();f.core.submit(state(false,0,""),true,(s,e)->fail("Cancelled result"));f.core.cancel();assertTrue(f.core.blocksSending(PEER));assertNotNull(f.core.pendingFor(PEER));f.disk.drain();assertTrue(f.requests.isEmpty());assertTrue(f.core.blocksSending(PEER));assertEquals(1,f.core.pending().size());}
    @Test public void lostResponseRetryUsesExactRequestAndAckIsDurableBeforeSuccess()throws Exception {Fixture f=new Fixture();List<String> result=new ArrayList<>();f.core.submit(state(false,0,""),true,(s,e)->result.add(e));f.disk.drain();String original=f.last().body.toString();f.last().reply.complete(0,new JSONObject(),"TIMEOUT");assertEquals(List.of("BLOCK_REQUEST_UNCONFIRMED"),result);PeerBlockJournal.Pending intent=f.core.pendingFor(PEER);f.core.retry(intent,(s,e)->result.add(e));f.disk.drain();assertEquals(original,f.last().body.toString());f.ack(true);assertEquals(1,result.size());assertEquals(1,f.core.pending().size());f.disk.drain();assertEquals("",result.get(1));assertTrue(f.core.pending().isEmpty());assertTrue(f.store().statuses.get(PEER).blocked);assertTrue(f.core.blocksSending(PEER));}
    @Test public void confirmedBlockSurvivesNewCoordinatorAndLowerRevisionIsRejected()throws Exception {Fixture f=new Fixture();f.core.submit(state(false,0,""),true,(s,e)->{});f.disk.drain();f.ack(true);f.disk.drain();f.core.close();PeerBlockCoordinator restored=new PeerBlockCoordinator((o,a)->f.store(),(m,p,b,o,r)->f.requests.add(new Request(m,p,b,o,r)),f.disk,Runnable::run,()->{});restored.bindSession(owner(ACCOUNT));assertTrue(restored.blocksSending(PEER));f.disk.drain();assertTrue(restored.blocksSending(PEER));List<String> result=new ArrayList<>();restored.fetch(PEER,(s,e)->result.add(e));f.last().reply.complete(200,json(false,0,""),"");assertEquals(List.of("INVALID_BLOCK_STATE"),result);assertTrue(restored.blocksSending(PEER));}
    @Test public void failedUnblockNeverClearsConfirmedBlock()throws Exception {Fixture f=new Fixture();f.store().statuses.put(PEER,new PeerBlockJournal.Status(PEER,true,3,"demo-old",false));f.core.bindSession(null);f.core.bindSession(owner(ACCOUNT));f.disk.drain();f.core.submit(state(true,3,"demo-old"),false,(s,e)->{});f.disk.drain();assertTrue(f.core.blocksSending(PEER));f.last().reply.complete(503,new JSONObject(),"");assertTrue(f.core.blocksSending(PEER));assertFalse(f.core.pendingFor(PEER).blocked);assertTrue(f.store().statuses.get(PEER).blocked);}
    @Test public void profileSwitchNeverSendsOrDisplaysPreviousPendingIntent()throws Exception {Fixture f=new Fixture();f.core.submit(state(false,0,""),true,(s,e)->fail("Stale result"));f.core.bindSession(owner("demo-account-b"));f.disk.drain();assertTrue(f.requests.isEmpty());assertTrue(f.core.pending().isEmpty());assertEquals(1,f.store().pending.size());assertTrue(f.core.ready());}
    @Test public void lateAckAfterCancellationIsReconciledByGet()throws Exception {Fixture f=new Fixture();f.core.submit(state(false,0,""),true,(s,e)->fail("Stale result"));f.disk.drain();Request mutation=f.last();String id=mutation.body.getString("mutation_id");f.core.cancel();mutation.reply.complete(200,json(true,1,id),"");assertEquals(1,f.core.pending().size());List<String> result=new ArrayList<>();f.core.fetch(PEER,(s,e)->result.add(e));f.last().reply.complete(200,json(true,1,id),"");assertTrue(result.isEmpty());f.disk.drain();assertEquals(List.of(""),result);assertTrue(f.core.pending().isEmpty());assertTrue(f.core.blocksSending(PEER));}
    @Test public void staleCasNeverAutomaticallyRetriesOrDeletesPending()throws Exception {Fixture f=new Fixture();List<String> result=new ArrayList<>();f.core.submit(state(false,0,""),true,(s,e)->result.add(e));f.disk.drain();f.last().reply.complete(409,new JSONObject(),"");assertEquals(List.of("BLOCK_STATE_CHANGED"),result);assertEquals(1,f.requests.size());assertEquals(1,f.core.pending().size());f.core.fetch(PEER,(s,e)->{});f.last().reply.complete(200,json(false,2,"demo-other"),"");f.disk.drain();int calls=f.requests.size();f.core.retry(f.core.pendingFor(PEER),(s,e)->result.add(e));assertEquals(calls,f.requests.size());assertEquals("BLOCK_STATE_CHANGED",result.get(1));}
    @Test public void malformedAckDoesNotConfirmOrRemoveIntent()throws Exception {Fixture f=new Fixture();List<String> result=new ArrayList<>();f.core.submit(state(false,0,""),true,(s,e)->result.add(e));f.disk.drain();f.last().reply.complete(200,json(true,1,"demo-wrong-id"),"");assertEquals(List.of("INVALID_BLOCK_ACK"),result);assertEquals(1,f.core.pending().size());assertNull(f.core.known(PEER));assertTrue(f.store().statuses.isEmpty());}
    @Test public void failedConfirmedStateCommitKeepsPendingAndClosesProtectionGate()throws Exception {Fixture f=new Fixture();List<String> result=new ArrayList<>();f.core.submit(state(false,0,""),true,(s,e)->result.add(e));f.disk.drain();f.store().failConfirm=true;f.ack(true);f.disk.drain();assertEquals(List.of("BLOCK_STORAGE_FAILED"),result);assertTrue(f.core.failed());assertTrue(f.core.blocksSending(PEER));assertEquals(1,f.store().pending.size());}
    @Test public void acceptedUnblockReopensOnlyProtectionGateNotAnyRoom()throws Exception {Fixture f=new Fixture();f.store().statuses.put(PEER,new PeerBlockJournal.Status(PEER,true,1,"demo-old",false));f.core.bindSession(null);f.core.bindSession(owner(ACCOUNT));f.disk.drain();f.core.submit(state(true,1,"demo-old"),false,(s,e)->{});f.disk.drain();assertEquals("/v1/blocks/unblock",f.last().path);f.ack(false);f.disk.drain();assertFalse(f.core.blocksSending(PEER));assertFalse(f.store().statuses.get(PEER).blocked);assertEquals(2,f.store().statuses.get(PEER).revision);assertEquals(1,f.requests.size());}
    @Test public void acknowledgementCompletesStorageEvenAfterNavigation()throws Exception {Fixture f=new Fixture();f.core.submit(state(false,0,""),true,(s,e)->fail("Cancelled result"));f.disk.drain();f.ack(true);f.core.cancel();f.disk.drain();assertTrue(f.core.pending().isEmpty());assertTrue(f.core.blocksSending(PEER));assertTrue(f.store().statuses.get(PEER).blocked);}
    @Test public void ownPeerAndMaximumRevisionNeverProduceMutation()throws Exception {Fixture f=new Fixture();List<String> result=new ArrayList<>();f.core.fetch(ACCOUNT,(s,e)->result.add(e));f.core.submit(state(false,Integer.MAX_VALUE,"demo-last"),true,(s,e)->result.add(e));f.disk.drain();assertTrue(f.requests.isEmpty());assertEquals(2,result.size());}
    @Test public void localForgetPreservesConfirmedFloorAndDoesNotCallServer()throws Exception {Fixture f=new Fixture();f.store().statuses.put(PEER,new PeerBlockJournal.Status(PEER,true,1,"demo-old",false));f.core.bindSession(null);f.core.bindSession(owner(ACCOUNT));f.disk.drain();f.core.submit(state(true,1,"demo-old"),false,(s,e)->{});f.disk.drain();f.last().reply.complete(0,new JSONObject(),"TIMEOUT");int calls=f.requests.size();f.core.forgetAfterConfirmation(f.core.pendingFor(PEER),e->assertEquals("",e));f.disk.drain();assertEquals(calls,f.requests.size());assertTrue(f.core.pending().isEmpty());assertTrue(f.core.blocksSending(PEER));}
}
